}
inline void husky_i2c(TwoWire& bus, const char* block) {
    if (husky_busy) { rb_fail(block, "HuskyLens está ocupada: usa un solo proceso para comunicar"); return; }
    husky_wire = &bus; husky_serial = nullptr; husky_reset();
}
inline void husky_uart(HardwareSerial& serial, const char* block) {
