inline void husky_clear(const char* block) {
    if (!husky_available(block)) return;
    if (husky_busy) { rb_fail(block, "HuskyLens está ocupada: usa un solo proceso para comunicar"); return; }
    if (!husky_send(0x35, nullptr, 0)) rb_fail(block, "No se pudieron borrar los textos de HuskyLens");
