        for (uint8_t i = 0; i < 16 && husky_wire->available(); i++) {
            int value = husky_wire->read(); if (value < 0) break; husky_byte(uint8_t(value), block);
        }
    } else if (husky_serial) {
        for (uint8_t i = 0; i < 64 && husky_serial->available(); i++) {
            int value = husky_serial->read(); if (value < 0) break; husky_byte(uint8_t(value), block);
        }
