inline void husky_reset() {
    husky_ready = false; husky_count = 0; husky_detected = 0; husky_busy = true; husky_command = 0x2C;
    husky_started = millis(); husky_sent = millis()-100; husky_pos = 0; husky_done = false;
}
inline void husky_i2c(TwoWire& bus, const char* block) {
    if (husky_busy) { rb_fail(block, "HuskyLens está ocupada: usa un solo proceso para comunicar"); return; }
    husky_wire = &bus; husky_serial = nullptr; husky_reset();
}
inline void husky_uart(HardwareSerial& serial, const char* block) {
    if (husky_busy) { rb_fail(block, "HuskyLens está ocupada: usa un solo proceso para comunicar"); return; }
    husky_wire = nullptr; husky_serial = &serial; husky_reset();
}
inline bool husky_start(const char* block) {
    if (rb_failed) return true;
