    if (uint32_t(millis()-husky_started) >= 2000) {
        rb_fail(block, husky_wire ? "No responde la HuskyLens: revisa el modo I2C en Ajustes → Protocolo" : "No responde la HuskyLens: revisa Serial 9600 en Ajustes → Protocolo");
        husky_busy = false; return true;
    }
    if (uint32_t(millis()-husky_sent) >= 100) {
        husky_pos = 0; husky_send(0x2C, nullptr, 0); husky_sent = millis();
    }
