inline bool husky_available(const char* block) {
    if (!husky_ready) { rb_fail(block, "Configura HuskyLens al iniciar y espera a que termine"); return false; }
    return !rb_failed;
}
inline void husky_request(uint8_t command, const uint8_t* data, uint8_t length, const char* block) {
    if (!husky_available(block)) return;
    if (husky_busy) { rb_fail(block, "HuskyLens está ocupada: usa un solo proceso para comunicar"); return; }
    husky_busy = true; husky_command = command; husky_pos = 0; husky_done = false; husky_info = false;
    husky_started = millis();
    if (!husky_send(command, data, length)) { husky_busy = false; rb_fail(block, "No se pudo enviar la trama a HuskyLens"); }
}
inline bool husky_wait(const char* block) {
    if (rb_failed) return true;
    husky_poll(block);
