inline void husky_algorithm(const String& algorithm, const char* block) {
    uint8_t data[2] = { uint8_t(algorithm[0]-'0'), 0 };
    husky_request(0x2D, data, 2, block);
}
inline int husky_find(float id, uint8_t kind, const char* block) {
    if (!husky_available(block)) return -1;
    if (!isfinite(id) || id < 0 || id > 65535 || id != floorf(id)) { rb_fail(block, "El ID de HuskyLens debe ser un entero de 0 a 65535"); return -1; }
    for (uint8_t i = 0; i < husky_count; i++) {
        const HuskyResult& result = husky_results[i];
        if ((!kind || result.kind == kind) && (id == 0 ? result.value[4] > 0 : result.value[4] == uint16_t(id))) return i;
    }
