}
inline float husky_objects(const char* block) {
    return husky_available(block) ? husky_detected : 0;
}
inline void husky_text(const String& text, float x, float y, const char* block) {
    if (!husky_available(block)) return;
    if (husky_busy) { rb_fail(block, "HuskyLens está ocupada: usa un solo proceso para comunicar"); return; }
    if (!isfinite(x) || !isfinite(y) || x < 0 || x > 320 || y < 0 || y > 240 || x != floorf(x) || y != floorf(y)) {
        rb_fail(block, "Texto HuskyLens: x debe ser 0..320 e y 0..240, enteros"); return;
    }
    if (text.length() > 19) { rb_fail(block, "Texto HuskyLens: máximo 19 bytes"); return; }
    uint8_t data[23]; data[0] = uint8_t(text.length()); data[1] = x >= 255 ? 0xFF : 0;
    data[2] = uint16_t(x) % 255; data[3] = uint8_t(y);
    for (uint8_t i = 0; i < data[0]; i++) data[4+i] = uint8_t(text[i]);
    if (!husky_send(0x34, data, data[0]+4)) rb_fail(block, "No se pudo enviar el texto a HuskyLens");
}
inline void husky_clear(const char* block) {
    if (!husky_available(block)) return;
    if (husky_busy) { rb_fail(block, "HuskyLens está ocupada: usa un solo proceso para comunicar"); return; }
    if (!husky_send(0x35, nullptr, 0)) rb_fail(block, "No se pudieron borrar los textos de HuskyLens");
}
